	PRIMARY KEY (id), 
	CONSTRAINT ck_traffic_windows_valid_range CHECK (window_end > window_start), 
	CONSTRAINT uq_traffic_windows_source_scope_range UNIQUE (traffic_source_id, scope_type, scope_key, window_start, window_end), 
	FOREIGN KEY(traffic_source_id) REFERENCES traffic_sources (id) ON DELETE RESTRICT
);
