CREATE TABLE predictions (
	id UUID NOT NULL, 
	observation_window_id UUID NOT NULL, 
	model_version_id UUID, 
	forecast_window_start TIMESTAMP WITH TIME ZONE NOT NULL, 
	forecast_window_end TIMESTAMP WITH TIME ZONE NOT NULL, 
	risk_score NUMERIC(5, 2) NOT NULL, 
	risk_level VARCHAR(8) NOT NULL, 
	predicted_attack_type VARCHAR(80), 
	confidence_score NUMERIC(4, 3) NOT NULL, 
	is_fallback BOOLEAN DEFAULT 'false' NOT NULL, 
	is_uncertain BOOLEAN DEFAULT 'false' NOT NULL, 
	is_ood BOOLEAN DEFAULT 'false' NOT NULL, 
	explanation_json JSONB DEFAULT '[]' NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_predictions_valid_forecast_range CHECK (forecast_window_end > forecast_window_start), 
	CONSTRAINT ck_predictions_risk_score CHECK (risk_score >= 0 AND risk_score <= 100), 
	CONSTRAINT ck_predictions_confidence_score CHECK (confidence_score >= 0 AND confidence_score <= 1), 
	FOREIGN KEY(observation_window_id) REFERENCES traffic_windows (id) ON DELETE RESTRICT, 
	FOREIGN KEY(model_version_id) REFERENCES model_versions (id) ON DELETE SET NULL
);
CREATE INDEX ix_predictions_created_risk_level ON predictions (created_at, risk_level);
CREATE INDEX ix_predictions_forecast_range ON predictions (forecast_window_start, forecast_window_end);

